#include <iostream>
#include <cmath>
#include <limits>
#include <iomanip>

/**
 * @brief Calculates the perpendicular distance from a point to a plane.
 * 
 * The formula used is: d = |Ax₀ + By₀ + Cz₀ + D| / sqrt(A² + B² + C²)
 * where the plane equation is Ax + By + Cz + D = 0.
 * 
 * @param px The x-coordinate of the point.
 * @param py The y-coordinate of the point.
 * @param pz The z-coordinate of the point.
 * @param a  The coefficient A of the plane (x component).
 * @param b  The coefficient B of the plane (y component).
 * @param c  The coefficient C of the plane (z component).
 * @param d  The constant D of the plane.
 * @return   The floating-point distance. Invalid input throws an exception.
 */
double calculatePointPlaneDistance(double px, double py, double pz, double a, double b, double c, double d) {
    // Check that the normal vector of the plane is not zero (A, B, C cannot all be zero)
    double normalMagnitude = std::sqrt(a * a + b * b + c * c);

    if (normalMagnitude == 0.0) {
        throw std::invalid_argument("All plane coefficients (A, B, C) cannot be zero simultaneously.");
    }

    // Apply the distance formula
    double numerator = std::abs(a * px + b * py + c * pz + d);
    return numerator / normalMagnitude;
}

int main() {
    std::cout << std::fixed;
    std::cout << std::setprecision(2); // Set default float output precision for display

    double px, py, pz;
    double a, b, c, d;

    // Input for the point coordinates
    std::cout << "\n=== Point and Plane Distance Calculator ===" << std::endl;
    std::cout << "Enter the coordinates of the point (x y z): ";
    if (!(std::cin >> px >> py >> pz) || std::cin.fail()) {
        std::cerr << "Error: Failed to read point coordinates. Please ensure valid numbers are entered." << std::endl;
        return 1;
    }

    // Input for the plane coefficients (Plane equation: ax + by + cz + d = 0)
    std::cout << "Enter the coefficients of the plane (A B C D): ";
    if (!(std::cin >> a >> b >> c >> d) || std::cin.fail()) {
        std::cerr << "Error: Failed to read plane coefficients. Please ensure valid numbers are entered." << std::endl;
        return 1;
    }

    // Clear any bad input flags and consume remaining newline
    std::cin.clear();
    std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');

    try {
        // Perform the calculation
        double distance = calculatePointPlaneDistance(px, py, pz, a, b, c, d);

        // Output the result
        std::cout << "\n--- Result ---" << std::endl;
        std::cout << "The perpendicular distance from the point (" 
                  << px << ", " << py << ", " << pz << ") "
                  << "to the plane (" << a << "x + " << b << "y + " << c << "z + " << d << " = 0) is: "
                  << distance << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Calculation Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
